SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT SQL.SQLCODE
SPOOL user-smlt-preflight.log
SELECT OWNER,TABLE_NAME,COLUMN_NAME,DATA_TYPE,DATA_LENGTH,NULLABLE FROM ALL_TAB_COLUMNS WHERE OWNER='PMOWN' AND (TABLE_NAME LIKE '%SMLT_USER%' OR TABLE_NAME IN ('TN_PM_SMLT_STNG','TH_PM_SMLT_FLFMT_HSTRY','TN_PM_SMLT_RSLT_DTL','TN_PM_SMLT_RSLT_DTL_REG_EXCL','TN_PM_SMLT_SCSH_OPER_PLAN')) ORDER BY TABLE_NAME,COLUMN_ID;
SELECT C.TABLE_NAME,C.CONSTRAINT_NAME,C.CONSTRAINT_TYPE,C.R_CONSTRAINT_NAME,CC.COLUMN_NAME,CC.POSITION FROM ALL_CONSTRAINTS C LEFT JOIN ALL_CONS_COLUMNS CC ON C.OWNER=CC.OWNER AND C.CONSTRAINT_NAME=CC.CONSTRAINT_NAME WHERE C.OWNER='PMOWN' AND C.TABLE_NAME LIKE '%SMLT%' ORDER BY C.TABLE_NAME,C.CONSTRAINT_NAME,CC.POSITION;
SELECT INDEX_NAME,TABLE_NAME,COLUMN_EXPRESSION FROM ALL_IND_EXPRESSIONS WHERE INDEX_OWNER='PMOWN';
SELECT SEQUENCE_NAME,MIN_VALUE,MAX_VALUE,LAST_NUMBER,CYCLE_FLAG FROM ALL_SEQUENCES WHERE SEQUENCE_OWNER='PMOWN' AND SEQUENCE_NAME LIKE '%SMLT%';
SELECT DBMS_METADATA.GET_DDL('TABLE', TABLE_NAME, 'PMOWN') FROM ALL_TABLES WHERE OWNER='PMOWN' AND TABLE_NAME IN ('TN_PM_SMLT_USER_MSTR','TN_PM_SMLT_STNG','TH_PM_SMLT_FLFMT_HSTRY','TN_PM_SMLT_USER_CHKN_ISL','TN_PM_SMLT_USER_CHKN_BOOTH','TN_PM_SMLT_USER_CHKN_OPER_HR','TN_PM_SMLT_USER_DPTGT','TN_PM_SMLT_USER_DPTGT_OPER_HR','TN_PM_SMLT_SCSH_OPER_PLAN','TN_PM_SMLT_USER_FLT_PSG_AJMT','TN_PM_SMLT_RSLT_DTL');
SELECT SMLT_ID,COUNT(DISTINCT EXCN_YMD) DATE_CNT,COUNT(DISTINCT SMLT_TYPE) TYPE_CNT FROM PMOWN.TN_PM_SMLT_STNG GROUP BY SMLT_ID HAVING COUNT(DISTINCT EXCN_YMD) != 1 OR COUNT(DISTINCT SMLT_TYPE) != 1;
SELECT SMLT_ID FROM PMOWN.TN_PM_SMLT_STNG WHERE NOT REGEXP_LIKE(SMLT_ID,'^[0-9]{1,8}$');
SELECT * FROM PMOWN.TN_PM_SMLT_USER_MSTR WHERE SMLT_STTS IN ('New','Executing');
SELECT RSLT_SMLT_ID,COUNT(*) FROM PMOWN.TN_PM_SMLT_USER_MSTR WHERE RSLT_SMLT_ID IS NOT NULL GROUP BY RSLT_SMLT_ID HAVING COUNT(*)>1;
SELECT COUNT(*) RESULT_ROWS,SUM(WTNG_PSG_CNT) WAIT_SUM,SUM(TRNST_PSG_CNT) PROCESSED_SUM FROM PMOWN.TN_PM_SMLT_RSLT_DTL;
SPOOL OFF
